; ULTIMA.COM: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; UDATA: buffers, strings, tables (0100-5CDD).
;
; Overview: the data of the intro (INTRO.ASM). Before 0100, labels for the PSP: the int 20h
; at 0000, the FCB at 005C used for the chain load of BOOTUP.BIN and the spot at 00FE where
; the "int 21h" of the chain load is planted; ULTIMA has none of the library's tables CombatPlayer
; to CombatPartyTile, so they are placed at 0000 and in the PSP's command tail. Then the buffers the
; files are loaded into (PictureBuf: BLANK.IBM, then EXOD.IBM; NamePoints: NAME.DAT;
; AnimFrames: ANIMATE.DAT), the file names, RowTbl (the screen offset of each scan line,
; built at start-up) and the message shown when there is no CGA.
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN StartUp:NEAR
PUBLIC PspInt20
PUBLIC PspFcb
PUBLIC FcbCurBlock
PUBLIC FcbRecSize
PUBLIC FcbFileSize
PUBLIC FcbCurRec
PUBLIC ChainInt21
PUBLIC Location
PUBLIC PictureBuf
PUBLIC VideoSeg
PUBLIC NamePoints
PUBLIC DiskCheckResult
PUBLIC AnimFrames
PUBLIC DissolveRand
PUBLIC FileBlankIbm
PUBLIC FileExodIbm
PUBLIC FileNameDat
PUBLIC FileAnimateDat
PUBLIC FileBootupBin
PUBLIC RowTbl
PUBLIC MsgNoGraphics
PUBLIC CombatPlayer
PUBLIC ViewTiles
PUBLIC CombatPartyX
PUBLIC CombatPartyY
PUBLIC CombatUnderTile
PUBLIC CombatPartyTile
; PSP:0000 holds int 20h (PspInt20: jumped to when BOOTUP.BIN is missing). ViewTiles and CombatPlayer
; are the library's view tables, which ULTIMA does not use.
ORG 0h
PspInt20 label near
ViewTiles label byte
CombatPlayer label byte
; The PSP's first FCB (PspFcb) and its fields: current block (+0Ch), record size (+0Eh),
; file size (+10h), current record (+20h).
ORG 5Ch
PspFcb label byte
ORG 68h
FcbCurBlock label byte
ORG 6Ah
FcbRecSize label byte
ORG 6Ch
FcbFileSize label byte
ORG 7Ch
FcbCurRec label byte
; CombatPartyX-CombatPartyTile: library tables ULTIMA does not have, put in the command tail.
ORG 0A0h
PspSpareA0 label byte
CombatPartyX label byte
ORG 0A4h
PspSpareA4 label byte
CombatPartyY label byte
ORG 0A8h
PspSpareA8 label byte
CombatUnderTile label byte
ORG 0ACh
PspSpareAC label byte
CombatPartyTile label byte
; ChainInt21: the chain load plants "int 21h" here; after it, execution runs on into 0100.
ORG 0FEh
ChainInt21 label near
ORG 100h
	jmp StartUp	;@0100
	db 0h,0h	;@0103
; Location = the library's Location (the party's location in the other programs): INTRO sets it to 1.
Location label byte	;@0105
	db 16 dup (0)	;@0105
PictureBuf label byte
	db 16384 dup (0)	; 4000h: BLANK.IBM (copied to the screen), then EXOD.IBM	;@0115
; VideoSeg: the video segment, B800 (CGA).
VideoSeg label byte
	db 0h,0B8h	;@4115
NamePoints label byte
	db 533 dup (0)	; NAME.DAT, its first 215h bytes: 266 (x, y) points and the 0 that ends them	;@4117
DiskCheckResult label byte
	db 0h	; 0FFh: the intro hangs (StartUp_WaitDisk)	;@432C
AnimFrames label byte
	db 5888 dup (0)	; ANIMATE.DAT: 4 pictures x 4 shifts x 16 rows x 23 bytes	;@432D
; DissolveRand: the state of CopyPicture's pseudo-random dissolve.
DissolveRand label byte
	db 0E3h,9Dh	;@5A2D
FileBlankIbm label byte
	db 42h,4Ch,41h,4Eh,4Bh,2Eh,49h,42h,4Dh,0h	;@5A2F
FileExodIbm label byte
	db 45h,58h,4Fh,44h,2Eh,49h,42h,4Dh,0h	;@5A39
FileNameDat label byte
	db 4Eh,41h,4Dh,45h,2Eh,44h,41h,54h,0h	;@5A42
FileAnimateDat label byte
	db 41h,4Eh,49h,4Dh,41h,54h,45h,2Eh,44h,41h,54h,0h	;@5A4B
FileBootupBin label byte
	db 42h,4Fh,4Fh,54h,55h,50h,2Eh,42h,49h,4Eh,0h	; "BOOTUP.BIN"	;@5A57
RowTbl label byte
	db 600 dup (0)	; 300 words, the first 200 used: screen offset of scan lines 0-199	;@5A62
; MsgNoGraphics: "Unable to access graphics display."
MsgNoGraphics label byte
	db 55h,6Eh,61h,62h,6Ch,65h,20h,74h,6Fh,20h,61h,63h,63h,65h,73h,73h	;@5CBA
	db 20h,67h,72h,61h,70h,68h,69h,63h,73h,20h,64h,69h,73h,70h,6Ch,61h	;@5CCA
	db 79h,2Eh,0h	;@5CDA
CODE ENDS
END
